import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------------------------------------------------------------------------------
# Inline CUDA/C++ sources for custom operators
# ---------------------------------------------------------------------------------

elementwise_add_scalar_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_scalar_kernel(const float* input, float scalar, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        output[idx] = input[idx] + scalar;
    }
}

torch::Tensor elementwise_add_scalar_cuda(torch::Tensor input, float scalar) {
    auto size = input.numel();
    auto output = torch::zeros_like(input);

    const int threads = 256;
    const int blocks = (size + threads - 1) / threads;

    elementwise_add_scalar_kernel<<<blocks, threads>>>(input.data_ptr<float>(), scalar, output.data_ptr<float>(), size);
    return output;
}
"""

gelu_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__device__ inline float approximate_gelu(float x) {
    // Tanh-based approximation of GELU
    // 0.5 * x * (1.0 + tanh( sqrt(2/pi) * ( x + 0.044715 * x^3 ) ))
    const float kAlpha = 0.7978845608f;  // sqrt(2.0 / pi)
    const float kBeta = 0.044715f;
    float x3 = x * x * x;
    return 0.5f * x * (1.0f + tanhf(kAlpha * (x + kBeta * x3)));
}

__global__ void gelu_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        output[idx] = approximate_gelu(input[idx]);
    }
}

torch::Tensor gelu_cuda(torch::Tensor input) {
    auto size = input.numel();
    auto output = torch::zeros_like(input);

    const int threads = 256;
    const int blocks = (size + threads - 1) / threads;

    gelu_kernel<<<blocks, threads>>>(input.data_ptr<float>(), output.data_ptr<float>(), size);
    return output;
}
"""

elementwise_add_scalar_cpp_source = r"""
torch::Tensor elementwise_add_scalar_cuda(torch::Tensor input, float scalar);
"""

gelu_cpp_source = r"""
torch::Tensor gelu_cuda(torch::Tensor input);
"""

# Compile custom CUDA kernels into an inline extension
custom_ops = load_inline(
    name="custom_ops",
    cpp_sources=elementwise_add_scalar_cpp_source + gelu_cpp_source,
    cuda_sources=elementwise_add_scalar_source + gelu_source,
    functions=["elementwise_add_scalar_cuda", "gelu_cuda"],
    verbose=False,
)

# ---------------------------------------------------------------------------------
# Optimized Model using custom CUDA operators
# ---------------------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Optimized Model that performs a 3D transposed convolution (PyTorch),
    followed by custom scalar addition, layer normalization, average pooling,
    and custom GELU activation.
    """
    def __init__(
        self,
        in_channels,
        out_channels,
        kernel_size,
        stride,
        padding,
        output_padding,
        sum_weight,
        norm_shape,
        pool_kernel_size
    ):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            output_padding=output_padding
        )
        self.sum_weight = nn.Parameter(torch.tensor(sum_weight))
        self.norm = nn.LayerNorm(norm_shape)
        self.avg_pool = nn.AvgPool3d(kernel_size=pool_kernel_size)

    def forward(self, x):
        # 1) PyTorch 3D transpose convolution
        x = self.conv_transpose(x)

        # 2) Custom elementwise addition with sum_weight
        x = custom_ops.elementwise_add_scalar_cuda(x, float(self.sum_weight))

        # 3) Layer normalization
        x = self.norm(x)

        # 4) Average pooling (PyTorch)
        x = self.avg_pool(x)

        # 5) Custom GELU activation
        x = custom_ops.gelu_cuda(x)

        return x

